from ta5g_eth_interfaces.eth_interfaces import EthInterfaces
from ta5g_file_system import ta5g_file_system
from robot.api import logger


class SyslogManager:
    """
    Class for syslog manager methods.
    """

    def __init__(self, syslog_lib):
        self.syslog_lib = syslog_lib

    def start_syslog_instance(self, log_dir, log_prefix, remote_host, eth_name, alias, virtualenv_dir=None):
        """
        Start syslog with specified alias.
        :param string log_dir:  Path to directory where syslog file should be stored.
        :param string log_prefix: Prefix for name of file where collected data should be stored during collection.
        :param string remote_host:  Ip address of eNB host PC.
        :param string eth_name: Name of eth interface in form eth1, eth2 etc.
        :param string alias: Unique identifier for a certain syslog instance.
        """
        log_directory = ta5g_file_system().set_log_directory(log_dir, keep_underscores=True)
        full_log_name = '%s%s.log' % (log_prefix, remote_host)
        lmp_ip = EthInterfaces().get_eth_ip(eth_name=eth_name, remote_host=remote_host)
        self.syslog_lib.start_syslog(
            log_dir=log_directory, log_name=full_log_name, ip=lmp_ip, host_ip=remote_host, alias=alias, virtualenv_dir=virtualenv_dir
        )
        logger.debug("Syslog started with alias {}, IP: {}".format(alias, lmp_ip))

    def teardown_all_syslog_aliases(self):
        self.syslog_lib.teardown_all_aliases_for_syslog()
